function constructAlarmAddressSpace(server, addressSpace, eventObjects, done) {


  const opcua = coreServer.choreCompact.opcua;
  const LocalizedText = opcua.LocalizedText;
  const namespace = addressSpace.getOwnNamespace();

  const Variant = opcua.Variant;
  const DataType = opcua.DataType;
  const DataValue = opcua.DataValue;

  var flexServerInternals = this;

  this.sandboxFlowContext.set("Temperature_Indoor", 0);
  this.sandboxFlowContext.set("Glycol_Water_Temperature", 0);
  this.sandboxFlowContext.set("Effective_SetPoint", 0);


  coreServer.debugLog("init dynamic address space");
  const rootFolder = addressSpace.findNode("RootFolder");

  node.warn("construct new address space for OPC UA");

  const myDevice = namespace.addFolder(rootFolder.objects, { "browseName": "BACnet Device" });
  const gpioFolder = namespace.addFolder(myDevice, { "browseName": "GPIO" });
  const isoInputs = namespace.addFolder(gpioFolder, { "browseName": "Inputs" });
  const isoOutputs = namespace.addFolder(gpioFolder, { "browseName": "Outputs" });

  const gpioIR1 = namespace.addVariable({
    "organizedBy": isoInputs,
    "browseName": "Temperature_Indoor",
    "nodeId": "ns=1;s=Temperature_Indoor_",
    "dataType": "Double",
    "value": {
      "get": function () {
        return new Variant({
          "dataType": DataType.Double,
          "value": flexServerInternals.sandboxFlowContext.get("Temperature_Indoor")
        });
      },
      "set": function (variant) {
        flexServerInternals.sandboxFlowContext.set("Temperature_Indoor", parseFloat(variant.value));
        return opcua.StatusCodes.Good;
      }
    }
  });

  const gpioIR2 = namespace.addVariable({
    "organizedBy": isoInputs,
    "browseName": "Glycol_Water_Temperature",
    "nodeId": "ns=1;s=Glycol_Water_Temperature_",
    "dataType": "Double",
    "value": {
      "get": function () {
        return new Variant({
          "dataType": DataType.Double,
          "value": flexServerInternals.sandboxFlowContext.get("Glycol_Water_Temperature")
        });
      },
      "set": function (variant) {
        flexServerInternals.sandboxFlowContext.set(
          "Glycol_Water_Temperature",
          parseFloat(variant.value)
        );
        return opcua.StatusCodes.Good;
      }
    }
  });

  const gpioIR3 = namespace.addVariable({
    "organizedBy": isoInputs,
    "browseName": "Effective_SetPoint",
    "nodeId": "ns=1;s=Effective_SetPoint_",
    "dataType": "Double",
    "value": {
      "get": function () {
        return new Variant({
          "dataType": DataType.Double,
          "value": flexServerInternals.sandboxFlowContext.get("Effective_SetPoint")
        });
      },
      "set": function (variant) {
        flexServerInternals.sandboxFlowContext.set(
          "Effective_SetPoint",
          parseFloat(variant.value)
        );
        return opcua.StatusCodes.Good;
      }
    }
  });


  //------------------------------------------------------------------------------
  // Add a view
  //------------------------------------------------------------------------------
  const viewDI = namespace.addView({
    "organizedBy": rootFolder.views,
    "browseName": "RPIW0-Digital-Ins"
  });

  const viewDO = namespace.addView({
    "organizedBy": rootFolder.views,
    "browseName": "RPIW0-Digital-Outs"
  });

  viewDI.addReference({
    "referenceType": "Organizes",
    "nodeId": gpioIR1.nodeId
  });

  viewDI.addReference({
    "referenceType": "Organizes",
    "nodeId": gpioIR2.nodeId
  });

  viewDI.addReference({
    "referenceType": "Organizes",
    "nodeId": gpioIR3.nodeId
  });

  coreServer.debugLog("create dynamic address space done");
  node.warn("construction of new address space for OPC UA done");

  done();
}

